"""Measured-development camera amplitude brackets, full-profile sensitivity only."""
from datetime import datetime,timezone
import json
from pathlib import Path
import subprocess

import numpy as np

from analysis.render import runtime_env
from measure_noise_opening_stages import read_crops
from study_noise_neighbourhoods import ROOT,sha256,git
from study_noise_profile_decomposition import projected,same_profile_context
from study_noise_local_transport import compare


def gain_bracket(real_sigmas,simulated_sigma):
    real=np.asarray(real_sigmas,dtype=float);sim=np.asarray(simulated_sigma,dtype=float)
    if real.ndim!=2 or real.shape[1]!=3 or real.shape[0]<2 or sim.shape!=(3,) or not np.isfinite(real).all() or not np.isfinite(sim).all() or np.any(real<=0) or np.any(sim<=0):raise ValueError('Positive finite RGB sigmas required')
    ratios=real/sim
    return np.minimum(ratios.min(axis=0),1),np.maximum(ratios.max(axis=0),1)


def variants(low,high):
    result=[dict(name='baseline',factors=[1.,1.,1.]),dict(name='all_low',factors=list(low)),dict(name='all_high',factors=list(high))]
    for c in range(3):
        for label,values in (('low',low),('high',high)):
            f=[1.,1.,1.];f[c]=float(values[c]);result.append(dict(name=f'{c}_{label}',factors=f))
    return result


def run():
    start=datetime.now(timezone.utc);stamp=start.strftime('%Y%m%dT%H%M%SZ');base=ROOT/'docs/validation/raw'
    names=('repetabilite-distributions-noirs-v001-20261028T114512Z.json','distributions-residus-bruit-v001-20261028T113008Z.json','prediction-locale-transport-bruit-v001-20261028T110349Z.json')
    paths=[base/n for n in names];hashes=[sha256(p) for p in paths]
    repeat,simulation,original=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    old_path=Path(original['request']['path'])
    if sha256(old_path)!=original['request']['sha256']:raise ValueError('Original profile context changed')
    contexts={(c['iso'],c['roi']):c for c in json.loads(old_path.read_text(encoding='utf-8'))['cases'] if c['role']=='black'}
    simref={(r['iso'],r['roi']):r for r in simulation['records']}
    bounds={}
    for key in contexts:
        rows=[r for r in repeat['records'] if (r['iso'],r['roi'])==key and r['subset']=='development']
        # Compare the actual DCP input (final camera), not a different callback stage.
        sigmas=[r['stages']['pre_dcp_camera_rgb']['real']['sigma'] for r in rows]
        simulated=simref[key]['stages']['post_rcd_median_camera_rgb']['simulated_median_sigma']
        low,high=gain_bracket(sigmas,simulated)
        bounds[key]=dict(iso=key[0],roi=key[1],development_pair_indices=[r['pair_index'] for r in rows],low=low.tolist(),high=high.tolist(),variants=variants(low,high))
    tool=ROOT/'build-patch_noise/burst-tools/Release/iprProfileGainSensitivity.exe';tool_hash=sha256(tool)
    subprocess.run([str(tool),'--self-test'],check=True,env=runtime_env(tool),timeout=30)
    freeze=base/f'gel-sensibilite-gains-profil-bruit-v001-{stamp}.json'
    policy=dict(campaign_id='noise-profile-gain-sensitivity-freeze-'+stamp,schema_version=1,data_version=1,measured_at_utc=start.isoformat(),parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],bounds=list(bounds.values()),
        policy='Brackets from DEVELOPMENT real final-camera marginal sigmas / frozen simulated median sigmas, include1, no DCP output used. Nine fixed positive multiplicative RGB variants: baseline, joint extrema, six single-channel extrema. Apply whole camera samples, preserving nonnegative support but changing mean AND noise/covariance; mathematical sensitivity, not physically inferred gain uncertainty or noise-only calibration. All30 real black ROIs plus96 frozen simulated residual pairs, no fitting/selection on control, no production change.',
        source=Path(__file__).read_text(encoding='utf-8'),source_sha256=sha256(Path(__file__)))
    with freeze.open('x',encoding='utf-8') as h:json.dump(policy,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('FROZEN',freeze,flush=True)
    work=ROOT/'build-patch_noise/profile-gain-sensitivity'/stamp;work.mkdir(parents=True,exist_ok=False)
    cached={}
    for source,item in repeat['native'].items():
        if sha256(Path(item['path']))!=item['sha256'] or sha256(Path(item['pixels']['path']))!=item['pixels']['sha256']:raise ValueError('Real buffer changed')
        cached[source]=read_crops(Path(item['pixels']['path']),item['record'])
    samples_path=Path(simulation['pixels']['path']);native_path=Path(simulation['native']['path'])
    if sha256(samples_path)!=simulation['pixels']['sha256'] or sha256(native_path)!=simulation['native']['sha256']:raise ValueError('Simulation buffer changed')
    data=np.fromfile(samples_path,dtype='<f4');native=json.loads(native_path.read_text(encoding='utf-8'))
    fields=work/'fields.f32';cases=[]
    with fields.open('xb') as handle:
        def append(case_id,iso,roi,kind,subset,images):
            ctx=contexts[(iso,roi)]
            if sha256(Path(ctx['profile']))!=ctx['profile_sha256']:raise ValueError('DCP changed')
            c={k:ctx[k] for k in ('profile','profile_sha256','source_kelvin','baseline_exposure_ev','profile_exposure_compensation_ev','preserve_tone_curve_hue')}
            c.update(case_id=case_id,iso=iso,roi=roi,kind=kind,subset=subset,variants=bounds[(iso,roi)]['variants'])
            for name,img in zip(('a','b','fa','fb'),images):
                if img.shape!=(128,128,3) or not np.isfinite(img).all():raise ValueError('Invalid sensitivity crop')
                c[name]=handle.tell();handle.write(np.asarray(img,dtype='<f4').tobytes())
            cases.append(c)
        for r in repeat['records']:
            roi=r['roi'];a,b=r['paths'];ra,rb=[repeat['native'][p]['record'] for p in (a,b)];ctx=contexts[(r['iso'],roi)]
            if not same_profile_context(ra,rb) or ra['profile_sha256']!=ctx['profile_sha256'] or ra['source_kelvin']!=ctx['source_kelvin']:raise ValueError('Real DCP contexts differ')
            images=[cached[p][stage][roi][64:192,64:192] for stage in ('pre_dcp_camera_rgb','post_dcp_rec2020') for p in (a,b)]
            append(f'real-{r["pair_index"]}-{roi}',r['iso'],roi,'real',r['subset'],images)
        for row in native['records']:
            iso=1600 if row['case_id'].startswith('0-') else 51200;roi=int(row['case_id'].split('-')[1]);crops={}
            for s in row['samples']:
                offset=s['offset_bytes']//4;count=int(np.prod(s['shape']))
                if offset<0 or offset+count>data.size:raise ValueError('Invalid simulation extent')
                crops[(s['stage'],s['trial'])]=data[offset:offset+count].reshape(s['shape'])
            for i in range(0,32,2):
                append(f'sim-{row["case_id"]}-{i}',iso,roi,'simulated','conditional_mc',[crops[(stage,t)] for stage in ('post_rcd_median_camera_rgb','post_dcp_rec2020') for t in (i,i+1)])
    request=work/'request.json'
    with request.open('x',encoding='utf-8') as h:json.dump(dict(fields=str(fields),fields_sha256=sha256(fields),cases=cases),h,ensure_ascii=False,indent=1,allow_nan=False)
    out=work/'native.json';subprocess.run([str(tool),str(request),str(out)],check=True,env=runtime_env(tool),timeout=900)
    result_native=json.loads(out.read_text(encoding='utf-8'));byid={c['case_id']:c for c in cases};records=[]
    for row in result_native['records']:
        c=byid[row['case_id']];baseline=projected(next(v['covariance_working'] for v in row['variants'] if v['name']=='baseline'))
        records.append(dict(case_id=c['case_id'],iso=c['iso'],roi=c['roi'],kind=c['kind'],subset=c['subset'],baseline_replay_max_delta=row['baseline_replay_max_delta'],
            variants=[dict(name=v['name'],factors=v['factors'],versus_baseline=compare(projected(v['covariance_working']),baseline)) for v in row['variants']]))
    if len(records)!=126 or hashes!=[sha256(p) for p in paths] or tool_hash!=sha256(tool):raise ValueError('Coverage/provenance failure')
    now=datetime.now(timezone.utc);output=base/f'sensibilite-gains-profil-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    result=dict(campaign_id='noise-profile-gain-sensitivity-'+stamp,schema_version=1,data_version=1,started_at_utc=start.isoformat(),measured_at_utc=now.isoformat(),completed_at_utc=now.isoformat(),parents=policy['parents'],freeze=dict(path=str(freeze),sha256=sha256(freeze)),request=dict(path=str(request),sha256=sha256(request)),fields=dict(path=str(fields),sha256=sha256(fields)),native=dict(path=str(out),sha256=sha256(out)),tool=dict(path=str(tool),sha256=tool_hash),bounds=list(bounds.values()),records=records,
        units='Positive mathematical RGB multipliers; Rec2020/YCoCg covariance, dimensionless sigma ratios to same-pair baseline.',
        limitations='Factors bracket measured amplitude discrepancies, NOT uncertainty in actual metadata gains. Whole-sample multiplication changes means and noise together, so not pure covariance sensitivity or causal attribution. Finite9 variants are not exhaustive bounds on nonlinear transformation. Real control previously inspected; no independent validation. No factor selected to fit output, DCP change, production correction, RAW decode or final reserve access.',verdict='positive_camera_gain_sensitivity_not_calibrated_correction',commit=git('rev-parse','HEAD'))
    with output.open('x',encoding='utf-8') as h:json.dump(result,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('RESULT',output,flush=True)


if __name__=='__main__':run()
